import {addFlashPanel,updateFlashPanel} from './pico-flash-ui.js';
import {addROMPanel} from './pico-rom-ui.js';
import {isPico} from './unified-project.js';
import {PICO_BOARDS} from './pico-boards.js';
import {addUSBPanel,updateUSBPanel} from './pico-usb-ui.js';
export function installPicoPanel({getProject,getSnapshot,showDialog,send,save}){
 const button=document.createElement('button');button.textContent='Pico bağlantıları';button.hidden=true;document.querySelector('.menubar nav').append(button);
 const configuration=()=>getProject().settings.picoNetwork||{ssid:'WirevoLab',password:'wirevo1234',enabled:true};
 function addBLE(){const form=document.getElementById('pico-network-form');if(!form)return;const section=document.createElement('section');section.innerHTML='<h3>Sanal BLE UART</h3><p>Firmware: <code>wirevo_ble_advertise / read / write</code>. Bu laboratuvar BTstack veya fiziksel Bluetooth bağlantısı değildir.</p><button data-ble-connect>Bağlan</button> <button data-ble-disconnect>Bağlantıyı kes</button><form data-ble-send><input name="text" aria-label="Sanal BLE mesajı" maxlength="256" placeholder="PING"><button>Gönder</button></form><pre data-ble-received></pre>';form.after(section);section.querySelector('[data-ble-connect]').onclick=()=>send({type:'pico-ble',action:'connect'});section.querySelector('[data-ble-disconnect]').onclick=()=>send({type:'pico-ble',action:'disconnect'});section.querySelector('[data-ble-send]').onsubmit=e=>{e.preventDefault();send({type:'pico-ble',action:'send',text:e.currentTarget.elements.text.value});};updateBLE();}
 function updateBLE(){const e=document.querySelector('[data-ble-received]');if(!e)return;const b=getSnapshot()?.pico?.radio?.ble;e.textContent=b?(b.name+' · '+(b.connected?'bağlı':'reklam / bağlantı bekliyor')+'\nAlınan: '+(b.received||'—')):'Firmware henüz BLE reklamı başlatmadı.';}
 function updateChip(){const el=document.querySelector('[data-cyw43-chip]');if(!el)return;const c=getSnapshot()?.pico?.radio?.chip;el.textContent=c?['CYW43439 · '+(c.powered?'güç açık':'güç kapalı'),'gSPI: '+c.stats.transactions+' aktarım · okunan '+c.stats.readBytes+' / yazılan '+c.stats.writtenBytes+' bayt','Backplane: 0x'+c.window.toString(16)+' · RAM '+(c.ramBytes/1024)+' KiB · IRQ '+(c.irq?'aktif':'pasif'),c.lastError?'Son erişim: '+c.lastError:''].filter(Boolean).join('\n'):'Firmware derlenip çalıştırıldığında çip durumu burada görünür.';}
 function addChip(){if(!getProject().components.some(c=>c.type==='board'&&PICO_BOARDS[c.params.model]?.wireless))return;const form=document.getElementById('pico-network-form');if(!form)return;const section=document.createElement('section');section.innerHTML='<h3>CYW43 donanım hattı</h3><p>GP23 güç, GP25 CS, GP29 saat, GP24 ortak veri/IRQ. gSPI kayıtları ve backplane RAM erişimi C koduna bağlıdır. Özgün çip işlemcisi/ROM ve radyo yürütülmez. <a href="./pico-cyw43-example.c" download>GPIO üzerinden C örneğini indir</a>.</p><pre data-cyw43-chip style="white-space:pre-wrap"></pre>';form.before(section);updateChip();}
 function addEnvironment(){const area=document.getElementById('pico-session-status');if(!area)return;const e=getProject().settings.picoEnvironment||{temperatureC:27,vsys:5,vbus:true},section=document.createElement('section');section.innerHTML='<h3>Pico ortam girişleri</h3><p>Dahili sıcaklık sensörü ve VSYS/3 ADC ölçümü. Bunlar ayarlanabilir simülasyon girişleridir; kartın termal/güç devresi hesaplanmaz. <a href="./pico-hardware-example.c" download>IRQ / DMA / ADC C örneğini indir</a>.</p><form id="pico-environment-form"><label>Sıcaklık (°C) <input name="temperatureC" type="number" min="-40" max="125" step="0.1" required></label><label>VSYS (V) <input name="vsys" type="number" min="0" max="5.5" step="0.01" required></label><label><input name="vbus" type="checkbox"> USB VBUS var</label><button>Ortamı uygula</button></form><pre data-pico-environment-result></pre>';area.after(section);const form=section.querySelector('form');form.elements.temperatureC.value=e.temperatureC;form.elements.vsys.value=e.vsys;form.elements.vbus.checked=e.vbus;form.onsubmit=ev=>{ev.preventDefault();const config={temperatureC:Number(form.elements.temperatureC.value),vsys:Number(form.elements.vsys.value),vbus:form.elements.vbus.checked};getProject().settings.picoEnvironment=config;save();send({type:'pico-environment',config});section.querySelector('[data-pico-environment-result]').textContent='Ortam kaydedildi; sonraki ADC ölçümleri yeni değerleri kullanır.';};}
 function terminal(){if(!isPico(getProject())||!getSnapshot()?.pico?.usb?.connected||getSnapshot()?.pico?.usb?.kind!=='cdc'||document.getElementById('serial-form').hidden)return;document.getElementById('terminal-port').textContent='USB CDC ACM';document.getElementById('uart-format').textContent='Sanal USB host';}
 button.onclick=()=>{const p=getProject(),b=PICO_BOARDS[p.components.find(c=>c.type==='board')?.params.model],s=getSnapshot()?.pico;
 showDialog('Pico · USB / çift çekirdek / sanal ağ','<p>USB CDC/HID/MSC/DFU, PIO/DMA ve iki ARM çekirdeği derlenmiş C koduyla çalışır. USB terminali için <code>stdio_usb_init()</code>, döngüde <code>tud_task()</code> kullanın; <code>stdio_usb_connected()</code> ile host hazır olmasını bekleyin.</p><pre id="pico-session-status"></pre>'+(b?.wireless?'<p><strong>Sanal Wi-Fi laboratuvarı</strong> · gerçek internete veya bilgisayarın Wi-Fi adaptörüne bağlanmaz. CYW43 firmware/radyo emülasyonu değildir. UDP echo hedefi: <code>192.168.4.1:7</code>. C API: <code>pico/cyw43_arch.h</code> + <code>wirevo/net.h</code>.</p><form id="pico-network-form"><label>SSID <input name="ssid" maxlength="32" required></label><label>Sanal test parolası <input name="password" maxlength="63"></label><label><input name="enabled" type="checkbox"> Sanal AP açık</label><button>Ağ ayarlarını uygula</button></form>':'<p>Bu modelde dahili kablosuz donanım bulunmaz. Kablosuz deneyleri için W/WH kartı seçin.</p>')+'<p><a href="./notices/PICO-MODEL.md" target="_blank">API kapsamı ve örnek kodlar</a></p>');
 document.getElementById('pico-session-status').textContent=s?['USB '+(s.usb.kind||'device')+': '+(s.usb.connected?'bağlı':'bekliyor'),...s.cores.map(c=>'Core '+c.id+': '+(c.running?'çalışıyor':'kapalı')+' · '+c.cycles+' çevrim · PC 0x'+c.pc.toString(16)),b?.wireless?'Sanal radyo: '+({0:'bağlı değil',1:'bağlanıyor',2:'IP bekliyor',3:'bağlı','-1':'bağlantı reddedildi','-2':'AP bulunamadı','-3':'kimlik doğrulama başarısız'}[s.radio.link]||s.radio.link):''].join('\n'):'Henüz çalışan firmware yok.';
 const form=document.getElementById('pico-network-form');if(form){const config=configuration();form.elements.ssid.value=config.ssid;form.elements.password.value=config.password;form.elements.enabled.checked=config.enabled;form.onsubmit=e=>{e.preventDefault();p.settings.picoNetwork={ssid:form.elements.ssid.value,password:form.elements.password.value,enabled:form.elements.enabled.checked};save();send({type:'pico-network',config:p.settings.picoNetwork});document.getElementById('pico-session-status').textContent='Sanal AP güncellendi. Firmware bağlantı isteğini yeniden çalıştırın.';};}
 };
 const open=button.onclick;button.onclick=()=>{open();addROMPanel({getProject});addFlashPanel({getSnapshot,getProject,send});addUSBPanel({getSnapshot,send});addBLE();addChip();addEnvironment();};
 return{render(){button.hidden=!isPico(getProject());updateBLE();updateChip();terminal();updateUSBPanel(getSnapshot());updateFlashPanel(getSnapshot());},payload:()=>({picoNetwork:configuration()})};
}
